package com.julesmeister.deutschcraft.feature.mission.domain

data class MissionObjective(
    val id: String,
    val missionTemplateId: String,
    val title: String,
    val description: String,
    val sequenceNumber: Int,
    val isRequired: Boolean,

    /*
     * Internal semantic completion rule used by Qwen.
     *
     * This value is never displayed in the UI.
     */
    val completionHint: String,

    /*
     * Progressive learner-facing hints generated by Qwen
     * together with this objective.
     */
    val coachingHints: List<String> =
        emptyList(),

    /*
     * German vocabulary useful for satisfying the current
     * objective.
     */
    val targetVocabulary: List<String> =
        emptyList(),

    /*
     * German model sentences appropriate for this
     * objective.
     */
    val examplePhrases: List<String> =
        emptyList()
) {

    val primaryHint: String?
        get() =
            coachingHints.firstSanitizedValue()

    val primaryVocabulary: String?
        get() =
            targetVocabulary.firstSanitizedValue()

    val primaryExamplePhrase: String?
        get() =
            examplePhrases.firstSanitizedValue()

    /*
     * Provides safe learner-facing guidance for missions
     * created before the new hint fields existed.
     */
    val displayGuidance: String
        get() =
            primaryHint
                ?: description
                    .trim()
                    .takeIf(String::isNotBlank)
                ?: DEFAULT_GUIDANCE

    /*
     * Returns the hint at the requested stage.
     *
     * If the requested index exceeds the available hints,
     * the final hint is reused.
     */
    fun coachingHintAt(
        index: Int
    ): String? {
        val availableHints =
            coachingHints.sanitizedValues()

        if (availableHints.isEmpty()) {
            return null
        }

        val safeIndex =
            index.coerceIn(
                minimumValue =
                    0,
                maximumValue =
                    availableHints.lastIndex
            )

        return availableHints[
            safeIndex
        ]
    }

    private fun List<String>.firstSanitizedValue():
            String? {
        return asSequence()
            .map(String::trim)
            .firstOrNull(String::isNotBlank)
    }

    private fun List<String>.sanitizedValues():
            List<String> {
        return asSequence()
            .map(String::trim)
            .filter(String::isNotBlank)
            .distinct()
            .toList()
    }

    private companion object {
        const val DEFAULT_GUIDANCE =
            "Setze das Gespräch fort, um dieses Ziel " +
                    "zu erreichen."
    }
}